 relative;\r\n  z-index: 10;\r\n}\r\n\r\n.header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n}\r\n\r\n.logo-wrapper {\r\n  display: flex;\r\n  align-items: center;\r\n}\r\n.logo {\r\n  max-height: 75px;\r\n  width: auto;\r\n  object-fit: contain;\r\n  filter: sepia(0.6) contrast(1.2);\r\n}\r\n\r\n.badge-official {\r\n  background: #3e2723;\r\n  color: #f4ebd0;\r\n  padding: 0.6rem 1.8rem;\r\n  border-radius: 2px;\r\n  border: 1px solid #b8860b;\r\n  font-family: 'Special Elite', monospace;\r\n  font-weight: 700;\r\n  font-size: 0.85rem;\r\n  letter-spacing: 2px;\r\n  text-transform: uppercase;\r\n  box-shadow: 0 2px 5px rgba(0,0,0,0.2);\r\n}\r\n\r\n.body {\r\n  margin: 5px 0;\r\n}\r\n\r\n.tagline {\r\n  color: #795548;\r\n  font-family: 'Special Elite', monospace;\r\n  font-size: 0.9rem;\r\n  text-transform: uppercase;\r\n  letter-spacing: 3px;\r\n  margin-bottom: 0.4rem;\r\n  font-weight: 600;\r\n}\r\n\r\n.student-name {\r\n  font-family: 'Playfair Display', serif;\r\n  font-size: 3rem;\r\n  color: #2c1810;\r\n  margin: 0.2rem 0 0.6rem;\r\n  font-weight: 900;\r\n  font-style: italic;\r\n  letter-spacing: 1px;\r\n}\r\n\r\n.description {\r\n  color: #5d4037;\r\n  font-size: 1.1rem;\r\n  margin-bottom: 0.3rem;\r\n  font-weight: 600;\r\n  font-family: 'Special Elite', monospace;\r\n}\r\n\r\n.course-title {\r\n  font-family: 'Playfair Display', serif;\r\n  font-size: 1.8rem;\r\n  color: #8b4513;\r\n  font-weight: 900;\r\n  margin: 0.4rem 0 1rem;\r\n  line-height: 1.2;\r\n  text-transform: uppercase;\r\n  letter-spacing: 1px;\r\n}\r\n\r\n.score-container {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  background: #f4ebd0;\r\n  padding: 0.5rem 2rem;\r\n  border-radius: 2px;\r\n  border: 1px solid #b8860b;\r\n}\r\n.score-label {\r\n  color: #5d4037;\r\n  font-weight: 700;\r\n  font-size: 0.85rem;\r\n  text-transform: uppercase;\r\n  letter-spacing: 2px;\r\n  font-family: 'Special Elite', monospace;\r\n